<?php require 'config.php';login_required();$admin=$_SESSION['role']==='admin';if($admin){$stats=['Book titles'=>$pdo->query('SELECT COUNT(*) FROM books')->fetchColumn(),'Available copies'=>$pdo->query('SELECT COALESCE(SUM(available),0) FROM books')->fetchColumn(),'Books on loan'=>$pdo->query("SELECT COUNT(*) FROM loans WHERE status='issued'")->fetchColumn(),'Student members'=>$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn()];$rows=$pdo->query("SELECT l.*,b.title,u.name FROM loans l JOIN books b ON b.id=l.book_id JOIN users u ON u.id=l.user_id ORDER BY l.issued_at DESC LIMIT 8")->fetchAll();}else{$s=$pdo->prepare("SELECT l.*,b.title FROM loans l JOIN books b ON b.id=l.book_id WHERE l.user_id=? ORDER BY l.issued_at DESC");$s->execute([$_SESSION['uid']]);$rows=$s->fetchAll();$stats=['Current loans'=>count(array_filter($rows,fn($r)=>$r['status']==='issued')),'Books returned'=>count(array_filter($rows,fn($r)=>$r['status']==='returned'))];}layout_start('Dashboard');?><div class="stats"><?php foreach($stats as $k=>$v):?><article><small><?=e($k)?></small><strong><?=e($v)?></strong></article><?php endforeach;?></div><?php if($admin):?><div class="actions"><a href="books.php">＋ Manage books / issue / return</a><a href="members.php">♙ View members</a><a href="reports.php">▤ Circulation reports</a></div><?php else:?><div class="hero"><div><small>YOUR COMMUNITY READING SPACE</small><h2>Find your next favourite book.</h2><p>Browse the catalogue and keep track of your borrowing history.</p><a class="button" href="books.php">Browse books</a></div><span>▤</span></div><?php endif;?><section class="panel"><h2><?= $admin?'Recent circulation':'My borrowing history'?></h2><?php if(!$rows):?><p class="muted">No borrowing records yet.</p><?php else:?><div class="scroll"><table><tr><th>Book</th><?php if($admin):?><th>Reader</th><?php endif;?><th>Issued</th><th>Due</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><?php if($admin):?><td><?=e($r['name'])?></td><?php endif;?><td><?=e($r['issued_at'])?></td><td><?=e($r['due_date'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div><?php endif;?></section><?php layout_end();?>